// OAuth2 授权码 + PKCE（S256）：code_challenge 计算与 token 端点校验
const crypto = require('crypto');

function b64urlEncode(input) {
  const buf = Buffer.isBuffer(input) ? input : Buffer.from(String(input), 'utf8');
  return buf.toString('base64').replace(/=+$/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}

// RFC 7636 附录 B 的官方测试向量
const CODE_VERIFIER = 'dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk';
const codeChallenge = b64urlEncode(crypto.createHash('sha256').update(CODE_VERIFIER).digest());
console.log('method=S256');
console.log('code_verifier=' + CODE_VERIFIER);
console.log('code_challenge=' + codeChallenge);

// 授权端点：客户端发来的 challenge 存到服务端（与 state 一起）
const stored = {
  code: 'authcode-001',
  codeChallenge,
  codeChallengeMethod: 'S256',
  state: 'xyz-state-888',
};

// ① 回调校验 state（防 CSRF）：必须与授权请求时下发的 state 完全一致
function checkState(received) { return received === stored.state; }
console.log('state_ok=' + checkState('xyz-state-888'));
console.log('state_tampered_ok=' + checkState('attacker-state'));

// ② token 端点校验 code_verifier：重算 challenge 必须与存的一致，且只接受 S256
function exchange(codeVerifier, method) {
  if (method !== 'S256') return { ok: false, reason: 'plain-not-allowed' };
  const recomputed = b64urlEncode(crypto.createHash('sha256').update(codeVerifier).digest());
  if (recomputed !== stored.codeChallenge) return { ok: false, reason: 'verifier-mismatch' };
  return { ok: true, token: 'access-token-issued' };
}
console.log('exchange_ok=' + exchange(CODE_VERIFIER, 'S256').ok);
console.log('exchange_wrong_verifier=' + JSON.stringify(exchange('attacker-verifier', 'S256')));
console.log('exchange_plain_rejected=' + JSON.stringify(exchange(CODE_VERIFIER, 'plain')));
console.log('pkce_blocks_code_interception=' + (exchange('attacker-verifier', 'S256').ok === false));
